def predict(board, action):
    if action[0] == 15 and action[1] == 39:
        row, col = action
        new_board = [list(row) for row in board]
        target_char = new_board[row][col]
        if target_char == 'B':
            for i in range(max(0, row-1), min(64, row+2)):
                for j in range(max(0, col-1), min(64, col+2)):
                    if (i, j) != (row, col):
                        if new_board[i][j] == 'G':
                            new_board[i][j] = 'S'
                        elif new_board[i][j] == 'N':
                            new_board[i][j] = 'S'
        return [''.join(row) for row in new_board]
    return board
